      if (b.queue.includes(memberId)) return fail('already holding');
      if (!b.loan && b.queue.length === 0) return fail('book is available; borrow it');
      b.queue.push(memberId);
      m.holds.push(bookId);
      return { ok: true, position: b.queue.length };
